# Colours (R, G, B)
PAPER = (253, 252, 248)
NAVY = (18, 38, 66)
NAVY_LIGHT = (32, 58, 92)
RED = (178, 34, 34)
INK = (22, 22, 22)
GREY = (110, 110, 108)
CARD_A = (244, 243, 238)
CARD_B = (255, 255, 255)
WHITE = (255, 255, 255)
RULE = (200, 198, 190)


def _chunk(data, name):
    return struct.pack(">I", len(data)) + name + data + struct.pack(
        ">I", binascii.crc32(name + data) & 0xFFFFFFFF
    )


def encode_png(rgb, width, height):
    """Encode raw RGB bytes as a deterministic PNG (colour type 2, no interlace)."""
    raw = bytearray()
    stride = width * 3
    for y in range(height):
        raw.append(0)  # filter: None
        raw.extend(rgb[y * stride:(y + 1) * stride])
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    comp = zlib.compress(bytes(raw), 9)
    png = b"\x89PNG\r\n\x1a\n"
    png += _chunk(ihdr, b"IHDR")
    png += _chunk(comp, b"IDAT")
    png += _chunk(b"", b"IEND")
    return png


class Canvas:
    def __init__(self, width, height, bg):
        self.width = width
        self.height = height
        self.pix = bytearray(bg * (width * height))

    def set(self, x, y, colour):
        if 0 <= x < self.width and 0 <= y < self.height:
            i = (y * self.width + x) * 3
            self.pix[i:i + 3] = bytes(colour)

    def rect(self, x, y, w, h, colour):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.width, x + w)
        y1 = min(self.height, y + h)
        for yy in range(y0, y1):
            base = (yy * self.width + x0) * 3
            row = bytes(colour) * (x1 - x0)
            self.pix[base:base + (x1 - x0) * 3] = row


    def blit(self, x, y, rgb, w, h):
        """Copy a raw RGB thumbnail (bytes, w x h) onto the canvas."""
        for yy in range(h):
            base = ((y + yy) * self.width + x) * 3
            src = yy * w * 3
            self.pix[base:base + w * 3] = rgb[src:src + w * 3]

    def char(self, x, y, ch, scale, colour):
        glyph = _G.get(ch, _G[" "])
        for r, bits in enumerate(glyph):
            for c in range(5):
                if bits & (1 << (4 - c)):
                    px = x + c * scale
                    py = y + r * scale
                    self.rect(px, py, scale, scale, colour)

    def text(self, x, y, s, scale, colour):
        s = s.upper()
        cx = x
        for ch in s:
            self.char(cx, y, ch, scale, colour)
            cx += 6 * scale
        return cx

    def text_width(self, s, scale):
        return len(s) * 6 * scale - scale

    def centred(self, y, s, scale, colour):
        w = self.text_width(s, scale)
        self.text((self.width - w) // 2, y, s, scale, colour)


def wrap(text, max_chars):
    """Greedy word wrap; returns a list of lines, each <= max_chars."""
    words = text.split()
    lines = []
    cur = ""
    for w in words:
        nxt = w if not cur else cur + " " + w
        if len(nxt) <= max_chars:
            cur = nxt
        else:
            if cur:
                lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def render():
    c = Canvas(WIDTH, HEIGHT, PAPER)

    # Header band
    c.rect(0, 0, WIDTH, 158, NAVY)
    c.rect(0, 158, WIDTH, 6, RED)
    c.centred(28, TITLE, 7, WHITE)
    c.centred(102, SUBTITLE, 3, (200, 210, 225))
    c.text(48, 102, "10 STORIES", 2, (200, 210, 225))

    # Items: 2-column grid, 5 rows. Each card: photo thumb on the left,
    # 3-line headline on the right, number badge on the thumb corner.
    margin = 20
    gap_x = 12
    gap_y = 12
    card_w = (WIDTH - 2 * margin - gap_x) // 2
    card_h = 148
    y0 = 180
    for idx, item in enumerate(ITEMS, start=1):
        col = (idx - 1) % 2
        row = (idx - 1) // 2
        x = margin + col * (card_w + gap_x)
        y = y0 + row * (card_h + gap_y)
        bg = CARD_A if idx % 2 == 1 else CARD_B
        c.rect(x, y, card_w, card_h, bg)
        # Photo thumbnail
        tx, ty = x + 10, y + (card_h - THUMB_H) // 2
        rgb = zlib.decompress(base64.b64decode(PHOTOS[idx]))
        c.blit(tx, ty, rgb, THUMB_W, THUMB_H)
        # Thin border around the thumb
        c.rect(tx, ty, THUMB_W, 2, NAVY)
        c.rect(tx, ty + THUMB_H - 2, THUMB_W, 2, NAVY)
        c.rect(tx, ty, 2, THUMB_H, NAVY)
        c.rect(tx + THUMB_W - 2, ty, 2, THUMB_H, NAVY)
        # Number badge on the thumb's top-left corner
        c.rect(tx, ty, 30, 30, RED if idx <= 3 else NAVY_LIGHT)
        num = str(idx)
        sc = 3
        nw = c.text_width(num, sc)
        c.text(tx + (30 - nw) // 2, ty + (30 - 7 * sc) // 2, num, sc, WHITE)
        # Headline, wrapped to at most 3 lines (26 chars at scale 2)
        lines = wrap(item, 26)[:3]
        text_x = x + 10 + THUMB_W + 10
        ty_text = y + (card_h - len(lines) * 22) // 2 + 2
        for line in lines:
            c.text(text_x, ty_text, line, 2, INK)
            ty_text += 22

    # Footer
    fy = HEIGHT - 40
    c.rect(20, fy - 10, WIDTH - 40, 2, RULE)
    c.text(20, fy + 6, FOOTER, 1, GREY)
    return bytes(c.pix)


def main():
    out_dir = Path(os.environ.get("OUTPUT_DIR", "/output"))
    out_dir.mkdir(parents=True, exist_ok=True)
    png = encode_png(render(), WIDTH, HEIGHT)
    out_path = out_dir / "entry.png"
    out_path.write_bytes(png)
    print(f"Wrote {len(png)} bytes to {out_path} ({WIDTH}x{HEIGHT})")


if __name__ == "__main__":
    main()
